/* Standalone, offline proposal prototype. No production storage is read or changed. */
const params = new URLSearchParams(location.search);
let screen = params.get('screen') || 'welcome';
let language = 'en';
let name = 'Alex';
let animal = 'Fox';
let unit = 0;
let solved = false;
let currentCase = 1;
let selected = null;
let history = [];
let board = Array(12).fill('tray');
let feedback = '';
let hintStep = 0;
let sound = false;
let desk = false;
let data = { group: 'Team', filter: 'All', sort: 'Normal order', view: 'Chart', answer: null };
const app = document.getElementById('app');
const copy = {
 en: {sound:'Sound',profile:'Profile',bureau:'THE LITTLE DETECTIVE BUREAU',hero:'Crack the clue.<br>Math it through!',description:'A little mystery. A little maths. A whole lot of “I did it!” Explore 27 cases at your own pace.',make:'Make it official',name:'Detective name',placeholder:'What should we call you?',partner:'Choose your partner',color:'Partner colour',start:'Start investigation',save:'Save profile',saved:'Saved on this device. No account needed.',hello:'Hello, Detective',choose:'Choose a unit. Your next mystery is waiting.',keep:'Follow the clues. Take your time.',cases:'cases solved',rookie:'Rookie',spotter:'Clue Spotter',nextlevel:'100 XP to level 2',units:['Numbers & operations','Algebra & reasoning','Measurement & geometry','Data analysis'],unit:'UNIT',case:'CASE',open:'Open case',upnext:'Up next',unlock:'Solve this case to unlock the next.',locked:'Locked',solved:'Case solved!',replay:'Solved cases',mission:'Share 12 biscuits equally among 3 evidence bags.',missing:'The missing biscuits',sharing:'Equal sharing',clues:'Clues',left:'left',drag:'Drag or tap a clue.',selected:'Choose a bag for this clue.',how:'How to move',place:'Bag',empty:'Place clues here',undo:'Undo',reset:'Reset',check:'Check',hint:'Hint',timer:'No timer. Take your time.',little:'A little hint',hintsteps:['What would an equal share look like?','Try giving each bag one biscuit per round.','Tray empty? Compare the bags. Does each have the same amount?'],back:'Back',another:'Another hint',try:'Let me try',review:'Look again',retry:'Try sharing equally. Each bag needs the same number.',waiting:'Move the clues still in the tray.',unlocked:'Next case unlocked!',next:'Next case',congrats:'Level up! Clue Spotter',dataTitle:'The sports day dashboard',dataMission:'In which event did Blue team score the most points?',dataHelp:'Change the tools. Tap a bar to answer.',dataSkill:'Dashboards: group & view',chartTitle:'Sports day points',answer:'Your answer',pick:'Tap a bar to choose your answer.',demo:'Choose how to move a clue',tap:'Tap twice',demo1:'Hold a clue. Move it into a bag. Let go!',demo2:'Tap a clue, then tap its bag.',done:'Profile saved.',footer:'Crack the Clue, Math It Through!',note:'Grade 3 · Phase B · Learn at your own pace',edit:'Edit detective profile',retrytools:'Look again. Check the tools and your chosen answer.'},
 id: {sound:'Suara',profile:'Profil',bureau:'BIRO DETEKTIF KECIL',hero:'Pecahkan petunjuk.<br>Hitung jalan keluarnya!',description:'Sedikit misteri. Sedikit matematika. Banyak rasa “Aku bisa!” Jelajahi 27 kasus sesukamu.',make:'Resmikan sekarang',name:'Nama detektif',placeholder:'Siapa namamu?',partner:'Pilih partner',color:'Warna partner',start:'Mulai penyelidikan',save:'Simpan profil',saved:'Tersimpan di perangkat ini. Tanpa akun.',hello:'Halo, Detektif',choose:'Pilih unit. Misteri berikutnya menantimu.',keep:'Ikuti petunjuk. Tidak perlu terburu-buru.',cases:'kasus selesai',rookie:'Detektif Pemula',spotter:'Pencari Petunjuk',nextlevel:'100 XP ke level 2',units:['Bilangan & operasi hitung','Aljabar & penalaran','Pengukuran & geometri','Analisis data'],unit:'UNIT',case:'KASUS',open:'Buka kasus',upnext:'Selanjutnya',unlock:'Selesaikan kasus ini untuk membuka berikutnya.',locked:'Terkunci',solved:'Kasus terpecahkan!',replay:'Kasus selesai',mission:'Bagi 12 biskuit sama rata ke 3 kantong bukti.',missing:'Biskuit yang hilang',sharing:'Berbagi sama rata',clues:'Petunjuk',left:'tersisa',drag:'Seret atau ketuk petunjuk.',selected:'Pilih kantong untuk petunjuk ini.',how:'Cara memindahkan',place:'Kantong',empty:'Taruh petunjuk di sini',undo:'Urungkan',reset:'Ulangi',check:'Periksa',hint:'Petunjuk',timer:'Tanpa timer. Santai saja.',little:'Sedikit petunjuk',hintsteps:['Seperti apa bagian yang sama banyak?','Coba beri tiap kantong satu biskuit setiap putaran.','Baki kosong? Bandingkan kantongnya. Apakah isinya sama banyak?'],back:'Kembali',another:'Petunjuk lain',try:'Aku coba dulu',review:'Cek lagi',retry:'Coba bagi sama rata. Tiap kantong perlu jumlah yang sama.',waiting:'Pindahkan petunjuk yang masih di baki.',unlocked:'Kasus berikutnya terbuka!',next:'Kasus berikutnya',congrats:'Naik level! Pencari Petunjuk',dataTitle:'Dasbor hari olahraga',dataMission:'Di lomba apa tim Biru mendapat poin terbanyak?',dataHelp:'Ubah alatnya. Ketuk batang untuk menjawab.',dataSkill:'Dasbor: kelompok & tampilan',chartTitle:'Poin hari olahraga',answer:'Jawabanmu',pick:'Ketuk batang untuk memilih jawaban.',demo:'Pilih cara memindahkan petunjuk',tap:'Ketuk dua kali',demo1:'Tahan petunjuk. Geser ke kantong. Lepaskan!',demo2:'Ketuk petunjuk, lalu ketuk kantongnya.',done:'Profil tersimpan.',footer:'Pecahkan Petunjuk, Hitung Jalan Keluarnya!',note:'Kelas 3 · Fase B · Belajar sesuai ritmemu',edit:'Edit profil detektif',retrytools:'Cek lagi alat dan jawaban pilihanmu.'}
};
const counts = [10,5,4,8];
const sampleSpecs = {
 10: { title:['The ribbon trail','Jejak pita'], skill:['Measuring length','Mengukur panjang'], mission:['Convert each ribbon clue to centimeters, then match its length.','Ubah setiap petunjuk pita ke sentimeter, lalu cocokkan panjangnya.'], labels:['50 cm','1 m','1 m + 50 cm','½ m','2 × 50 cm','3 × 50 cm'], groups:['50 cm','100 cm','150 cm'], hints:['How many centimeters make one meter?','For half a meter, split that amount into two equal parts.','Use centimeters for every piece. Then add the lengths.'] },
 12: { title:['The final combination','Kombinasi terakhir'], skill:['Two-step problems','Soal dua langkah'], mission:['Solve inside the brackets first. Find the final safe code.','Hitung dalam kurung dahulu. Temukan kode brankas terakhir.'], labels:['(8 + 2) × 2','(9 + 6) × 2','(7 + 3) × 4','(36 ÷ 3) + 8','(6 × 6) − 6','(50 − 30) × 2'], groups:['20','30','40'], hints:['Find the brackets. Which calculation should you try first?','Replace the bracketed part with your first result.','Look outside the brackets. Which operation is still waiting?'] }
};
const localized = a => a[language==='en'?0:1];
const activeSpec = () => sampleSpecs[currentCase];
const displayCase = () => currentCase===10||currentCase===12?1:currentCase;
let completedSamples = new Set();

const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t = () => copy[language];
const btn = (label, action, primary=false, extra='') => `<button type="button" class="btn ${primary?'btn-primary':''}" data-action="${action}" ${extra}>${label}</button>`;
function header(){const c=t();return `<header class="app-header"><button class="wordmark" data-action="home" aria-label="Math It! home"><span class="mark">⌕</span><span>Math It!</span></button><div class="header-actions"><button class="micro-button" data-action="sound" aria-pressed="${sound}" aria-label="${c.sound}: ${sound?'on':'off'}"><span class="sound-label">${c.sound} </span>${sound?'On':'Off'}</button><div class="language" aria-label="Language">${['id','en'].map(l=>`<button class="${language===l?'active':''}" data-lang="${l}" aria-pressed="${language===l}">${l.toUpperCase()}</button>`).join('')}</div><button class="micro-button" data-action="desk" aria-label="Desk preference" aria-pressed="${desk}">${desk?'Night':'Day'}</button><button class="micro-button profile-trigger" data-action="profile" aria-label="${c.profile}" ${screen==='welcome'?'disabled':''}><span class="mini-avatar">${esc(animal[0])}</span><span>${esc(name)}</span></button></div></header>`;}
function footer(){return `<footer class="product-footer"><span><strong>Math It!</strong> &nbsp; ${t().footer}</span><span>${t().note}</span></footer>`;}
function form(edit=false){const c=t();return `<form class="form-card" id="detective-form"><div class="avatar-placeholder" aria-label="Partner illustration placeholder">${esc(animal.toUpperCase())}</div><h2>${edit?c.edit:c.make}</h2><label class="field-label" for="detective-name">${c.name}</label><input class="text-field" id="detective-name" name="name" placeholder="${c.placeholder}" value="${edit?esc(name):''}" required maxlength="24" autocomplete="nickname"><fieldset><legend>${c.partner}</legend><div class="partner-options">${['Fox','Cat','Bear'].map(a=>`<label class="partner"><input type="radio" name="animal" value="${a}" ${animal===a?'checked':''}><span class="face">${a[0]}</span>${a}</label>`).join('')}</div></fieldset><fieldset><legend>${c.color}</legend><div class="swatches">${['Teal','Yellow','Coral'].map((color,i)=>`<label class="swatch" aria-label="${color} shown in grayscale"><input type="radio" name="coat" value="${color}" ${i===0?'checked':''}></label>`).join('')}</div></fieldset><button class="btn btn-primary btn-wide" type="submit">${edit?c.save:c.start} <span aria-hidden="true">→</span></button><p class="reassurance">${c.saved}</p></form>`;}
function welcome(){const c=t();return `<main class="page welcome"><section class="welcome-copy"><span class="pill">${c.bureau}</span><h1>${c.hero}</h1><p>${c.description}</p><div class="illustration-placeholder" aria-label="Bakery scene illustration placeholder"><b aria-hidden="true">□ &nbsp; ⌕ &nbsp; □</b><span>BAKERY MYSTERY / ILLUSTRATION</span><p>12 biscuits. 3 bags. One curious detective.</p></div></section>${form()}</main>`;}
function heading(){const c=t();return `<div class="page-heading"><div><h1>${c.hello} ${esc(name)}.</h1><p>${screen==='casebook'?c.choose:c.keep}</p></div><div class="progress-summary"><div class="progress-count">${solved?'1':'0'} / 27<small>${c.cases}</small></div><div class="rank"><strong>${solved?'02':'01'} · ${solved?c.spotter:c.rookie}</strong><div class="progress-track"><span style="width:${solved?'33':'0'}%"></span></div><small>${solved?'100 XP · 200 XP to level 3':c.nextlevel}</small></div></div></div>`;}
function casebook(){const c=t();const titles=[solved?['The secret number code','Kode angka rahasia'][language==='en'?0:1]:c.missing,['The final combination','Kombinasi terakhir'][language==='en'?0:1],['The ribbon trail','Jejak pita'][language==='en'?0:1],['The sports day dashboard','Dasbor hari olahraga'][language==='en'?0:1]];return `<main class="page">${heading()}<nav class="units" aria-label="Learning units">${c.units.map((title,i)=>`<button class="unit ${unit===i?'active':''}" data-unit="${i}" aria-pressed="${unit===i}"><small>${c.unit} 0${i+1}</small><strong>${title}</strong><span>${completedSamples.has(i)?'1':'0'} / ${counts[i]} ${c.cases}</span></button>`).join('')}</nav><section class="feature"><div><span class="eyebrow">${c.unit} 0${unit+1} / ${c.case} ${unit===3?'08':unit===0&&solved?'02':'01'}</span><h2>${titles[unit]}</h2><p>${unit===0&&!solved?c.mission:unit===3?c.dataMission:language==='en'?'A new mystery to practise your mathematical thinking.':'Misteri baru untuk melatih penalaran matematika.'}</p>${btn(c.open+' <span aria-hidden="true">→</span>','open',true)}</div><div class="illustration-placeholder"><b>${unit===0?'12 ÷ 3':unit===3?'▥':'? + ?'}</b><span>CASE ILLUSTRATION</span></div></section><div class="section-heading"><h2>${c.upnext}</h2><span>${c.unlock}</span></div><div class="case-grid">${[unit===0?(solved?'The parcel totals':'The secret number code'):'Next case',unit===0?(solved?'The disappearing stamps':'The parcel totals'):'Following case'].map((title,i)=>`<button class="case-card" disabled><div class="case-meta"><span>${c.case} 0${i+2+(unit===0&&solved?1:0)}</span><span>${c.locked}</span></div><h3>${title}</h3><p>${c.unlock}</p></button>`).join('')}</div><details class="solved-casebook"><summary>${c.replay} (${solved?1:0})</summary>${solved?btn(c.missing,'clues'): `<p style="margin-top:12px">${language==='en'?'Your solved cases will appear here.':'Kasus yang selesai akan muncul di sini.'}</p>`}</details></main>`;}
function caseNav(dataCase=false){return `<nav class="case-nav" aria-label="Case navigation"><button data-action="home" aria-label="Casebook">⌂</button><span>${t().unit} ${dataCase?'04':'01'}</span><button data-action="clues" class="${!dataCase&&currentCase===1?'current':''}" ${dataCase||unit!==0?'disabled':''}>${dataCase?'06':'01'}</button><button data-action="second" class="${currentCase===2&&!dataCase?'current':''}" ${!solved||dataCase||unit!==0?'disabled':''}>${dataCase?'07':'02'}</button><button class="${dataCase?'current':''}" disabled>${dataCase?'08':'03'}</button></nav>`;}
function token(i){return `<button class="token ${activeSpec()?'expression-token':''} ${selected===i?'selected':''}" draggable="true" data-token="${i}" aria-label="${currentCase===2?'Clue '+sortLabels[i]:activeSpec()?'Clue '+activeSpec().labels[i]:'Biscuit '+(i+1)}" aria-pressed="${selected===i}">${currentCase===2?sortLabels[i]:activeSpec()?activeSpec().labels[i]:'•'}</button>`;}
const sortLabels=['8','9','12','15','16','7','12'];
function groupLabel(z){return activeSpec()?activeSpec().groups[['a','b','c'].indexOf(z)]:currentCase===2?['Multiple of 3','Multiple of 4','Neither'][['a','b','c'].indexOf(z)]:`${t().place} ${z.toUpperCase()}`;}
function clueContent(){const c=t();return `<div class="workspace-intro"><span role="status">${selected===null?c.drag:c.selected}</span><button class="text-button" data-action="demo">${c.how}</button></div><section class="tray" data-drop="tray" aria-label="${c.clues}"><div class="tray-heading"><strong>${c.clues}</strong><span>${board.filter(z=>z==='tray').length} ${c.left}</span></div><div class="tokens">${board.map((z,i)=>z==='tray'?token(i):'').join('')}</div></section><div class="groups">${['a','b','c'].map(z=>{const n=board.filter(p=>p===z).length;const needs=feedback==='retry'&&(currentCase===2||activeSpec()||n!==4);return `<section class="group ${n?'':'empty'} ${needs?'needs-review':''}" data-drop="${z}" aria-label="${groupLabel(z)}"><div class="group-heading">${btn(groupLabel(z),'place',false,`data-zone="${z}"`)}<span>${n} ${c.clues.toLowerCase()}</span></div><div class="tokens">${board.map((p,i)=>p===z?token(i):'').join('')}</div>${needs?`<span class="look-again">${c.review}</span>`:''}</section>`}).join('')}</div>${feedbackMarkup()}<div class="board-toolbar"><div>${btn(c.undo,'undo',false,history.length?'':'disabled')}${btn(c.reset,'reset')}</div>${btn(c.check,'check',true,feedback==='success'?'disabled':'')}</div>`;}
function feedbackMarkup(){const c=t();if(!feedback)return '';if(feedback==='success')return `<section class="feedback success" role="status"><div><strong>${c.solved} &nbsp; +100 XP</strong><span>${c.congrats}<br>${c.unlocked}</span></div>${btn(c.next+' →','next',true)}</section>`;return `<div class="feedback" role="status"><strong style="font-size:12px">${c.review}</strong>${screen==='data'?c.retrytools:board.includes('tray')?c.waiting:c.retry}</div>`;}
function clueScreen(){const c=t();return `<main class="page">${heading()}${caseNav()}<article class="case-board"><header class="briefing"><span class="eyebrow"><span>${c.unit} 0${unit+1} / ${c.case} 0${displayCase()}</span><span>${activeSpec()?localized(activeSpec().skill):currentCase===2?'Multiples':c.sharing}</span></span><h2>${activeSpec()?localized(activeSpec().title):currentCase===2?'The secret number code':c.missing}</h2><p>${activeSpec()?localized(activeSpec().mission):currentCase===2?'Sort the cards. Some may fit both groups.':c.mission}</p></header><div class="board-content">${clueContent()}</div><div class="board-footer">${btn('? &nbsp; '+c.hint,'hint')}<span>${c.timer}</span></div></article></main><nav class="mobile-dock" aria-label="Clue destinations">${['a','b','c'].map(z=>`<button data-action="place" data-zone="${z}">${groupLabel(z)} · ${board.filter(p=>p===z).length}</button>`).join('')}</nav>`;}
const scores=[[30,20,25],[15,35,20],[25,15,40],[20,25,30]];
function rows(){let r;if(data.group==='Event')r=['Running','Sack race','Tug of war'].map((label,j)=>({label,value:data.filter==='All'?scores.reduce((s,a)=>s+a[j],0):scores[['Red','Blue','Green','Yellow'].indexOf(data.filter)][j]}));else r=['Red','Blue','Green','Yellow'].map((label,i)=>({label,value:data.filter==='All'?scores[i].reduce((a,b)=>a+b,0):scores[i][['Running','Sack race','Tug of war'].indexOf(data.filter)]}));if(data.sort!=='Normal order')r.sort((a,b)=>data.sort==='Most first'?b.value-a.value:a.value-b.value);return r;}
function tool(key,label,help,options){return `<div class="tool"><label for="tool-${key}">${label}</label><p>${help}</p><select id="tool-${key}" data-tool="${key}">${options.map(o=>`<option ${data[key]===o?'selected':''}>${o}</option>`).join('')}</select></div>`;}
function dataScreen(){const c=t();const r=rows();const max=Math.ceil(Math.max(...r.map(a=>a.value))/4/5)*5*4;return `<main class="page">${heading()}${caseNav(true)}<article class="case-board"><header class="briefing"><span class="eyebrow"><span>${c.unit} 04 / ${c.case} 08</span><span>${c.dataSkill}</span></span><h2>${c.dataTitle}</h2><p>${c.dataMission}</p></header><div class="board-content"><div class="workspace-intro">${c.dataHelp}</div><section class="dashboard-tools" aria-label="Dashboard tools">${tool('group','Bars show','Choose what each bar stands for.',['Team','Event'])}${tool('filter','Filter','Show only one kind.',['All',...(data.group==='Team'?['Running','Sack race','Tug of war']:['Red','Blue','Green','Yellow'])])}${tool('sort','Sort','Put the bars in order.',['Normal order','Most first','Fewest first'])}${tool('view','View','Chart or exact numbers.',['Chart','Table'])}</section><section class="chart-panel"><h3>${c.chartTitle}</h3><p class="showing">Showing: ${data.group} / ${data.filter} / ${data.sort} · points</p>${data.view==='Chart'?`<div class="bars" role="group" aria-label="Sports day scores in points">${r.map(a=>`<div class="bar-row"><span>${a.label}</span><div class="bar-track"><button class="bar ${data.answer===a.label?'chosen':''}" data-pick="${a.label}" style="width:${a.value/max*100}%" aria-label="${a.label}, ${a.value} points" aria-pressed="${data.answer===a.label}"></button></div></div>`).join('')}</div><div class="axis" aria-hidden="true">${[0,1,2,3,4].map(i=>`<span>${max*i/4}</span>`).join('')}</div>`:`<table class="data-table"><thead><tr><th>${data.group}</th><th>Points</th><th>Answer</th></tr></thead><tbody>${r.map(a=>`<tr class="${data.answer===a.label?'chosen':''}"><td>${a.label}</td><td>${a.value}</td><td><button class="text-button" data-pick="${a.label}" aria-pressed="${data.answer===a.label}">${data.answer===a.label?'Chosen':'Choose'}</button></td></tr>`).join('')}</tbody></table>`}<p class="answer" role="status">${data.answer?c.answer+': <strong>'+esc(data.answer)+'</strong>':c.pick}</p></section>${feedbackMarkup()}<div class="board-toolbar">${btn(c.reset,'reset')}${btn(c.check,'checkdata',true,feedback==='success'?'disabled':'')}</div></div><div class="board-footer">${btn('? &nbsp; '+c.hint,'hint')}<span>${c.timer}</span></div></article></main>`;}
function render(notify=true){document.documentElement.lang=language;document.body.dataset.desk=desk?'night':'day';app.innerHTML=header()+(screen==='welcome'?welcome():screen==='casebook'?casebook():screen==='data'?dataScreen():screen==='profile'?`<main class="page profile-page"><span class="eyebrow">DETECTIVE CARD / SETTINGS</span>${form(true)}</main>`:clueScreen())+footer();bind();if(notify&&parent!==window)parent.postMessage({type:'mathit-screen',screen},location.protocol==='file:'?'*':location.origin);}
function go(next){screen=next;feedback='';selected=null;render();window.scrollTo(0,0);}
function move(i,destination){if(feedback==='success'||board[i]===destination)return;history.push([...board]);board[i]=destination;selected=null;feedback='';render(false);}
function resetBoard(){board=Array(activeSpec()?6:currentCase===2?7:12).fill('tray');history=[];selected=null;feedback='';}
function closeDialog(){document.querySelector('dialog')?.close();document.querySelector('dialog')?.remove();}
function dialog(kind){const c=t();const d=document.createElement('dialog');d.className='wire-dialog';d.setAttribute('aria-label',kind==='demo'?c.demo:c.little);if(kind==='demo'){d.innerHTML=`<div class="dialog-head"><h2>${c.demo}</h2><button class="close-button" data-close aria-label="Close">×</button></div><div class="demo-steps"><div class="demo-step"><b>● → □</b><strong>Drag</strong><p>${c.demo1}</p></div><div class="demo-step"><b>● &nbsp; □</b><strong>${c.tap}</strong><p>${c.demo2}</p></div></div>${btn(c.try,'close',true,'style="width:100%"')}`;}else{const prompt=activeSpec()?activeSpec().hints[hintStep]:currentCase===2?['Try counting in threes. Which cards do you reach?','Now count in fours. Could a card fit both groups?','Check both lists before choosing Neither.'][hintStep]:screen==='data'?['The answer is an event. What should each bar show?','Use the filter to keep only one team.','Bars close together? The table view shows exact numbers.'][hintStep]:c.hintsteps[hintStep];d.innerHTML=`<div class="dialog-head"><h2>${c.little}</h2><button class="close-button" data-close aria-label="Close hint">×</button></div><span class="eyebrow">${c.hint.toUpperCase()} ${hintStep+1} / 3</span><p>${prompt}</p><div class="hint-visual">${activeSpec()?'□ → ?':currentCase===2?['0 → 3 → ?','0 → 4 → ?','3 × □ ?  4 × □ ?'][hintStep]:screen==='data'?['▥ = ?','Filter → ?','Chart ⇄ Table'][hintStep]:['A: ?   B: ?   C: ?','● → A → B → C','A = B = C ?'][hintStep]}</div><div class="dialog-actions">${btn(c.back,'hintback',false,hintStep===0?'disabled':'')}${btn(c.another,'hintnext',false,hintStep===2?'disabled':'')}</div>${btn(c.try,'close',true,'style="width:100%;margin-top:12px"')}`;}
document.body.append(d);d.showModal();d.querySelector('[data-close]').onclick=closeDialog;d.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.action;if(a==='close')closeDialog();else{hintStep+=a==='hintback'?-1:1;closeDialog();dialog('hint');}});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});d.addEventListener('close',()=>d.remove());}
function bind(){document.querySelectorAll('[data-lang]').forEach(el=>el.onclick=()=>{const input=document.getElementById('detective-name');const value=input?.value;language=el.dataset.lang;render(false);if(value!==undefined)document.getElementById('detective-name').value=value;});document.querySelectorAll('[data-unit]').forEach(el=>el.onclick=()=>{unit=+el.dataset.unit;render(false);});document.querySelectorAll('[data-token]').forEach(el=>{el.onclick=()=>{if(feedback==='success')return;selected=selected===+el.dataset.token?null:+el.dataset.token;render(false);};el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.token);e.dataTransfer.effectAllowed='move';};});document.querySelectorAll('[data-drop]').forEach(el=>{el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();const raw=e.dataTransfer.getData('text/plain');const n=Number(raw);if(raw!==''&&Number.isInteger(n)&&n>=0&&n<board.length)move(n,el.dataset.drop);};el.onclick=e=>{if(selected!==null&&!e.target.closest('[data-token]')&&!e.target.closest('[data-action]'))move(selected,el.dataset.drop);};});document.querySelectorAll('[data-tool]').forEach(el=>el.onchange=()=>{data[el.dataset.tool]=el.value;if(el.dataset.tool==='group'){data.filter='All';data.answer=null;}feedback='';render(false);});document.querySelectorAll('[data-pick]').forEach(el=>el.onclick=()=>{data.answer=el.dataset.pick;feedback='';render(false);});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action,el));const f=document.getElementById('detective-form');if(f)f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f);const clean=String(fd.get('name')).trim();if(!clean){document.getElementById('detective-name').setCustomValidity('Please enter your detective name.');document.getElementById('detective-name').reportValidity();return;}const editing=screen==='profile';name=clean;animal=String(fd.get('animal'));go('casebook');if(editing){const m=document.createElement('p');m.className='save-message';m.setAttribute('role','status');m.textContent=t().done;document.querySelector('.page-heading').after(m);}};const input=document.getElementById('detective-name');if(input)input.oninput=()=>input.setCustomValidity('');document.querySelectorAll('input[name="animal"]').forEach(el=>el.onchange=()=>{animal=el.value;document.querySelector('.avatar-placeholder').textContent=animal.toUpperCase();});}
function action(a,el){if(a==='home')go(screen==='welcome'?'welcome':'casebook');else if(a==='profile')go('profile');else if(a==='sound'){sound=!sound;render(false);}else if(a==='desk'){desk=!desk;render(false);}else if(a==='open'){currentCase=unit===1?12:unit===2?10:unit===0&&solved?2:1;resetBoard();if(unit===3)go('data');else{go('clues');if(!solved&&!params.has('capture'))dialog('demo');}}else if(a==='clues'){currentCase=1;resetBoard();go('clues');}else if(a==='second'){currentCase=2;resetBoard();go('clues');}else if(a==='place'){if(selected!==null)move(selected,el.dataset.zone);else document.querySelector(`[data-drop="${el.dataset.zone}"]`)?.scrollIntoView({block:'center',behavior:'smooth'});}else if(a==='undo'){if(history.length){board=history.pop();selected=null;feedback='';render(false);}}else if(a==='reset'){resetBoard();data={group:'Team',filter:'All',sort:'Normal order',view:'Chart',answer:null};render(false);}else if(a==='check'){const correct=activeSpec()?board.every((z,i)=>['a','b','c','a','b','c'][i]===z):currentCase===2?board.every((z,i)=>['b','a','a','a','b','c','b'][i]===z):['a','b','c'].every(z=>board.filter(p=>p===z).length===4);feedback=correct?'success':'retry';if(correct){completedSamples.add(unit);if(unit===0)solved=true;}render(false);}else if(a==='checkdata'){feedback=data.group==='Event'&&data.filter==='Blue'&&data.answer==='Sack race'?'success':'retry';render(false);}else if(a==='hint'){hintStep=0;dialog('hint');}else if(a==='demo')dialog('demo');else if(a==='next'){if(screen==='data'||unit!==0){go('casebook');return;}currentCase=2;resetBoard();go('clues');}}
function preset(target){closeDialog();unit=target==='data'?3:0;completedSamples=new Set(target==='success'?[0]:[]);screen=target;currentCase=1;solved=false;resetBoard();data={group:'Team',filter:'All',sort:'Normal order',view:'Chart',answer:null};if(target==='success'){solved=true;board=Array.from({length:12},(_,i)=>['a','b','c'][Math.floor(i/4)]);feedback='success';}if(target==='retry'){board=Array.from({length:12},(_,i)=>i<5?'a':i<8?'b':'c');feedback='retry';}if(target==='hint'||target==='demo')screen='clues';render(false);if(target==='hint'||target==='demo')dialog(target);}
window.addEventListener('message',e=>{if(e.source!==parent)return;if(e.data?.type==='mathit-navigate')preset(e.data.screen);if(e.data?.type==='mathit-restart'){name='Alex';animal='Fox';language='en';unit=0;preset('welcome');}});
window.prototypeApi={preset, getState:()=>({screen,board:[...board],solved,feedback,data:{...data},name})};
preset(screen);
new ResizeObserver(()=>{if(parent!==window)parent.postMessage({type:'mathit-size',height:Math.ceil(app.getBoundingClientRect().height)},location.protocol==='file:'?'*':location.origin);}).observe(app);
